import { rmSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

// Runtime is generated by Blueprint's canonical stager during packaging.
// Remove prior output before RightKit scans Cargo manifests so embedded eval
// fixtures are never mistaken for Membrane source workspaces.
rmSync(fileURLToPath(new URL("../src-tauri/runtime", import.meta.url)), { recursive: true, force: true });

const result = spawnSync("pnpm", ["exec", "right-release", "build", "--platform", "mac"], {
  cwd: fileURLToPath(new URL("../", import.meta.url)),
  env: process.env,
  stdio: "inherit",
});
if (result.error) throw result.error;
if (result.status !== 0) process.exit(result.status ?? 1);
